/// Corner radii (pt). Theme-agnostic.
public enum NockerlRadius {
    public static let none: CGFloat = 0
    public static let track: CGFloat = 2
    public static let control: CGFloat = 12
    public static let panel: CGFloat = 12
    public static let card: CGFloat = 16
    public static let bubble: CGFloat = 20
    public static let bubbleTail: CGFloat = 6
    public static let pill: CGFloat = 9999
}

/// Elevation / drop-shadow blur levels (pt).
public enum NockerlElevation {
    public static let level1: CGFloat = 1
    public static let level2: CGFloat = 1.5
    public static let level3: CGFloat = 3
    public static let sheet: CGFloat = 5
    public static let blur: CGFloat = 0
}

/// Lift-shadow opacity ladder (Double 0..1): pair with NockerlElevation blur;
/// apply as shadowTint.opacity(NockerlShadowTintAlpha.levelN). NOT a dimension.
public enum NockerlShadowTintAlpha {
    public static let level1: Double = 0.28
    public static let level2: Double = 0.3
    public static let level3: Double = 0.33
    public static let sheet: Double = 0.35
}

/// Cyan-stroke weight scale (pt). The weight is SEMANTIC (design-laws §2):
/// widthFloating = hovering ON TOP of content; widthSelection = a CHOICE state
/// (pair with NockerlBorderOpacity.selection); widthIndicator = the sliding marker bar.
public enum NockerlBorder {
    public static let widthFloating: CGFloat = 1.5
    public static let widthSelection: CGFloat = 1
    public static let widthIndicator: CGFloat = 1
}

/// Stroke opacities (Double 0..1). Apply as accentPrimary.opacity(…). NOT dimensions.
public enum NockerlBorderOpacity {
    public static let selection: Double = 0.45
}

/// 4pt-grid spacing scale (pt).
public enum NockerlSpace {
    public static let space0: CGFloat = 0
    public static let space1: CGFloat = 4
    public static let space2: CGFloat = 8
    public static let space3: CGFloat = 12
    public static let space4: CGFloat = 16
    public static let space5: CGFloat = 20
    public static let space6: CGFloat = 24
    public static let space8: CGFloat = 32
    public static let space10: CGFloat = 40
    public static let space12: CGFloat = 48
    public static let space16: CGFloat = 64
    public static let spacePx: CGFloat = 1
    public static let space05: CGFloat = 2
}

