/// Motion durations (seconds). RATIFIED r3.
public enum NockerlMotionDuration {
    public static let instant: TimeInterval = 0
    public static let fast: TimeInterval = 0.12
    public static let base: TimeInterval = 0.2
    public static let slow: TimeInterval = 0.32
    public static let sheet: TimeInterval = 0.4
    public static let pulse: TimeInterval = 0.8
}

/// A cubic-bezier easing (control points). Feed `Animation.timingCurve`.
public struct NockerlBezier {
    public let x1: Double
    public let y1: Double
    public let x2: Double
    public let y2: Double
}

/// Motion easing curves. `standard` is THE default transition ease.
public enum NockerlMotionEasing {
    public static let standard = NockerlBezier(x1: 0.2, y1: 0, x2: 0, y2: 1)
    public static let emphasized = NockerlBezier(x1: 0.05, y1: 0.7, x2: 0.1, y2: 1)
    public static let exit = NockerlBezier(x1: 0.3, y1: 0, x2: 0.8, y2: 0.15)
}
